#include <iostream>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;

    size_t first = s.find_first_not_of('0');
    if (first == string::npos) {
        cout << 0 << '\n';
        return 0;
    }
    s.erase(0, first);

    size_t k = s.size() / 2;

    if (2 * k + 1 == s.size()) {
        bool isPower = (s[0] == '1');
        for (size_t i = 1; i < s.size() && isPower; ++i)
            isPower = (s[i] == '0');

        if (!isPower)
            ++k;
    }

    cout << k << '\n';
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;

    size_t start = s.find_first_not_of('0');
    if (start == string::npos) {
        cout << 0 << '\n';
        return 0;
    }

    size_t length = s.size() - start;
    bool powerOfTen = s[start] == '1';

    for (size_t i = start + 1; i < s.size() && powerOfTen; ++i) {
        if (s[i] != '0') powerOfTen = false;
    }

    cout << (powerOfTen ? length / 2 : (length + 1) / 2) << '\n';
    return 0;
}

